func trainingFeelingLabel(value string) string {
	switch value {
	case "1":
		return "muito mal"
	case "2":
		return "mal"
	case "3":
		return "razoavelmente"
	case "4":
		return "bem"
	case "5":
		return "muito bem"
	default:
		return "não indicada"
	}
}

